import numpy as np

def inverse_matrice(A):
    """Retourne l'inverse d'une matrice carrée A via numpy."""
    try:
        return np.linalg.inv(A)
    except np.linalg.LinAlgError:
        return "Matrice non inversible (déterminant nul)"

# Exemple
A = np.array([[2, 1], [5, 3]])
print(inverse_matrice(A))
